  "imagem": "https://admin.cnnbrasil.com.br/wp-content/uploads/sites/12/2023/03/Bolsa_Familia_15227288838.jpg?crop=1&h=630&w=1200",
  "imagemX": "https://admin.cnnbrasil.com.br/wp-content/uploads/sites/12/2023/03/Bolsa_Familia_15227288838.jpg?crop=1&h=630&w=1200",
